def merge_ranges(ranges):
    # Filter out empty ranges and sort by start
    valid = sorted((start, end) for start, end in ranges if start < end)
    merged = []
    for start, end in valid:
        if not merged:
            merged.append([start, end])
        else:
            last_start, last_end = merged[-1]
            if start <= last_end:  # overlapping or touching
                merged[-1][1] = max(last_end, end)
            else:
                merged.append([start, end])
    return [tuple(interval) for interval in merged]

from collections import defaultdict
import heapq
def topological(edges, nodes):
    adj = defaultdict(list)
    indegree = {node: 0 for node in nodes}
    seen = set()
    for u, v in edges:
        if (u, v) in seen:
            continue
        seen.add((u, v))
        adj[u].append(v)
        indegree[v] += 1
    zero = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(zero)
    result = []
    while zero:
        node = heapq.heappop(zero)
        result.append(node)
        for nb in adj[node]:
            indegree[nb] -= 1
            if indegree[nb] == 0:
                heapq.heappush(zero, nb)
    if len(result) != len(nodes):
        raise ValueError("Cycle")
    return result

def decode_runs(text):
    i = 0
    n = len(text)
    result = []
    while i < n:
        # Expect a count (digits)
        if i >= n or not text[i].isdigit():
            raise ValueError
        start = i
        while i < n and text[i].isdigit():
            i += 1
        count_str = text[start:i]
        if not count_str:
            raise ValueError
        count = int(count_str)
        if count == 0:
            raise ValueError
        # Expect a lowercase ASCII letter
        if i >= n or not ('a' <= text[i] <= 'z'):
            raise ValueError
        letter = text[i]
        i += 1
        result.append(letter * count)
    return ''.join(result)

from collections import OrderedDict
def lru(capacity, operations):
    cache = OrderedDict()
    results = []
    if capacity == 0:
        # Cache stores nothing, so all get operations return -1
        for op in operations:
            if op[0] == "get":
                results.append(-1)
            # put operations are ignored
        return results
    for op in operations:
        if op[0] == "put":
            _, key, value = op
            if key in cache:
                cache.move_to_end(key)
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op[0] == "get":
            _, key = op
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(-1)
    return results

def flatten(value):
    result = []
    if isinstance(value, (list, tuple)):
        for item in value:
            result.extend(flatten(item))
    else:
        result.append(value)
    return result

import heapq
def shortest(graph, start, end):
    if start == end:
        return 0
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, node = heapq.heappop(heap)
        if node == end:
            return d
        for neighbor, weight in graph.get(node, []):
            nd = d + weight
            if neighbor not in dist or nd < dist[neighbor]:
                dist[neighbor] = nd
                heapq.heappush(heap, (nd, neighbor))
    return None

from collections import deque
def window_max(values, k):
    if k <= 0:
        raise ValueError("k must be positive")
    if k > len(values):
        return []
    result = []
    dq = deque()  # stores indices of elements in decreasing order of values
    for i, val in enumerate(values):
        # Remove indices that are out of the current window
        while dq and dq[0] <= i - k:
            dq.popleft()
        # Remove indices of elements smaller than the current one
        while dq and values[dq[-1]] < val:
            dq.pop()
        dq.append(i)
        # Append the maximum for windows that have reached size k
        if i >= k - 1:
            result.append(values[dq[0]])
    return result

import copy
def deep_merge(left, right):
    if isinstance(left, dict) and isinstance(right, dict):
        merged = {}
        all_keys = set(left.keys()) | set(right.keys())
        for key in all_keys:
            if key in left and key in right:
                if isinstance(left[key], dict) and isinstance(right[key], dict):
                    merged[key] = deep_merge(left[key], right[key])
                else:
                    merged[key] = copy.deepcopy(right[key])
            elif key in left:
                merged[key] = copy.deepcopy(left[key])
            else:
                merged[key] = copy.deepcopy(right[key])
        return merged
    else:
        # If either argument is not a dictionary, return a deep copy of right
        return copy.deepcopy(right)

from collections import defaultdict, deque
def rate_limit(events, limit, window):
    if limit == 0:
        return [False] * len(events)
    queues = defaultdict(deque)
    result = []
    for t, key in events:
        q = queues[key]
        # Remove events that are outside the window
        while q and q[0] <= t - window:
            q.popleft()
        if len(q) < limit:
            q.append(t)
            result.append(True)
        else:
            result.append(False)
    return result

def json_pointer(value, pointer):
    if pointer == "":
        return value
    tokens = pointer.split('/')
    if tokens and tokens[0] == '':
        tokens = tokens[1:]
    current = value
    for token in tokens:
        # Decode ~0 and ~1 escapes
        decoded = []
        i = 0
        while i < len(token):
            if token[i] == '~':
                if i + 1 < len(token):
                    if token[i + 1] == '0':
                        decoded.append('~')
                        i += 2
                    elif token[i + 1] == '1':
                        decoded.append('/')
                        i += 2
                    else:
                        raise ValueError("Malformed escape")
                else:
                    raise ValueError("Malformed escape")
            else:
                decoded.append(token[i])
                i += 1
        token = ''.join(decoded)
        if isinstance(current, dict):
            if token not in current:
                raise ValueError("Missing path")
            current = current[token]
        elif isinstance(current, list):
            # Validate canonical decimal index
            if not token.isdigit():
                raise ValueError("Invalid list index")
            if token[0] == '0' and len(token) > 1:
                raise ValueError("Invalid list index")
            index = int(token)
            if index < 0 or index >= len(current):
                raise ValueError("Missing path")
            current = current[index]
        else:
            raise ValueError("Invalid path")
    return current

def stable_unique(values):
    result = []
    for v in values:
        if not any(u == v for u in result):
            result.append(v)
    return result

def parse_duration(text):
    if not text:
        raise ValueError("Empty input")
    unit_order = {'h': 3, 'm': 2, 's': 1}
    unit_seconds = {'h': 3600, 'm': 60, 's': 1}
    total = 0
    i = 0
    n = len(text)
    last_order = None
    seen = set()
    while i < n:
        if not text[i].isdigit():
            raise ValueError("Malformed input")
        start = i
        while i < n and text[i].isdigit():
            i += 1
        if start == i:
            raise ValueError("Malformed input")
        num = int(text[start:i])
        if i >= n:
            raise ValueError("Malformed input")
        unit = text[i]
        i += 1
        if unit not in unit_seconds:
            raise ValueError("Malformed input")
        if unit in seen:
            raise ValueError("Malformed input")
        current_order = unit_order[unit]
        if last_order is not None and current_order >= last_order:
            raise ValueError("Malformed input")
        last_order = current_order
        seen.add(unit)
        total += num * unit_seconds[unit]
    return total

def apply_patch(text, edits):
    n = len(text)
    # Validate each edit for basic range and order
    for start, end, replacement in edits:
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("Start and end must be integers")
        if start < 0 or end < 0 or start > end or end > n:
            raise ValueError(f"Invalid edit ({start}, {end}): must satisfy 0 <= start < end <= len(text)")
    # Check for duplicate start offsets
    starts = [edit[0] for edit in edits]
    if len(starts) != len(set(starts)):
        raise ValueError("Duplicate start offsets")
    # Sort edits by start position
    sorted_edits = sorted(edits, key=lambda e: e[0])
    # Check for overlapping spans
    prev_end = -1
    for start, end, _ in sorted_edits:
        if start < prev_end:
            raise ValueError("Overlapping edits")
        prev_end = end
    # Apply the edits
    result = []
    prev = 0
    for start, end, replacement in sorted_edits:
        if start > prev:
            result.append(text[prev:start])
        result.append(replacement)
        prev = end
    if prev < n:
        result.append(text[prev:])
    return ''.join(result)

def paginate(items, after, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    if after is None:
        filtered = items
    else:
        filtered = [item for item in items if item['id'] > after]
    filtered.sort(key=lambda x: x['id'])
    page = filtered[:limit]
    if len(page) < limit:
        next_cursor = None
    else:
        # page has exactly limit items
        if len(filtered) > limit:
            next_cursor = page[-1]['id']
        else:
            next_cursor = None
    return page, next_cursor

def expression(text):
    s = text
    n = len(s)
    i = 0

    def skip():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def peek():
        skip()
        if i < n:
            return s[i]
        return None

    def get():
        skip()
        if i < n:
            ch = s[i]
            i += 1
            return ch
        return None

    def parse_number():
        skip()
        if i < n and s[i].isdigit():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            return int(s[start:i])
        raise ValueError("Expected number")

    def parse_factor():
        ch = peek()
        if ch == '+':
            get()
            return parse_factor()
        if ch == '-':
            get()
            return -parse_factor()
        # check for '('
        ch = peek()
        if ch == '(':
            get()  # consume '('
            val = parse_expression()
            if peek() != ')':
                raise ValueError("Missing closing parenthesis")
            get()  # consume ')'
            return val
        # number
        if i < n and s[i].isdigit():
            return parse_number()
        raise ValueError("Invalid factor")

    def parse_term():
        val = parse_factor()
        while True:
            ch = peek()
            if ch == '*':
                get()
                val = val * parse_factor()
            else:
                break
        return val

    def parse_expression():
        val = parse_term()
        while True:
            ch = peek()
            if ch == '+':
                get()
                val = val + parse_term()
            elif ch == '-':
                get()
                val = val - parse_term()
            else:
                break
        return val

    result = parse_expression()
    skip()
    if i != n:
        raise ValueError("Invalid syntax")
    return result

def retry_delays(attempts, initial, cap):
    if attempts < 0 or initial < 0 or cap < 0:
        raise ValueError("Negative arguments are not allowed")
    delays = []
    delay = initial
    for _ in range(attempts):
        if delay > cap:
            delay = cap
        delays.append(delay)
        delay *= 2
    return delays

import csv
from io import StringIO
def csv_records(text):
    text = text.strip()
    if not text:
        return []
    reader = csv.reader(StringIO(text))
    rows = list(reader)
    if not rows:
        return []
    headers = rows[0]
    # Check for duplicate headers
    if len(headers) != len(set(headers)):
        raise ValueError("Duplicate headers")
    result = []
    for row in rows[1:]:
        if len(row) != len(headers):
            raise ValueError("Row has different number of fields")
        result.append(dict(zip(headers, row)))
    return result

def version_sort(versions):
    def key_func(v):
        # Split the version string into numeric parts
        parts = [int(x) for x in v.split('.')]
        # Remove trailing zero segments
        while parts and parts[-1] == 0:
            parts.pop()
        return parts
    # Use stable sort to retain input order for ties
    return sorted(versions, key=key_func)

def glob_match(pattern, text):
    if not pattern:
        return not text
    if pattern[0] == '*':
        # '*' can match zero or more characters
        return glob_match(pattern[1:], text) or (glob_match(pattern, text[1:]) if text else False)
    if pattern[0] == '?':
        # '?' matches any single character
        return len(text) > 0 and glob_match(pattern[1:], text[1:])
    # Otherwise, literal character
    if not text or pattern[0] != text[0]:
        return False
    return glob_match(pattern[1:], text[1:])

def memo_cycle(definitions, name):
    memo = {}
    visiting = set()

    def dfs(n):
        if n in memo:
            return memo[n]
        if n in visiting:
            raise ValueError("Cycle detected")
        visiting.add(n)
        definition = definitions.get(n)
        if definition is None:
            raise ValueError(f"Missing dependency {n}")
        if isinstance(definition, int):
            result = definition
        elif isinstance(definition, list):
            result = 0
            for dep in definition:
                dep_def = definitions.get(dep)
                if dep_def is None:
                    raise ValueError(f"Missing dependency {dep}")
                dep_val = dfs(dep)
                result += dep_val
        else:
            raise ValueError(f"Invalid definition for {n}")
        visiting.remove(n)
        memo[n] = result
        return result

    return dfs(name)
